import { useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selected, setSelected] = useState<Date>(() => startOfDay(new Date()));

  const handleChange = (date: Date) => {
    const normalized = startOfDay(date);
    setSelected(normalized);
    onChange?.(normalized);
  };

  const presets: { label: string; getDate: () => Date }[] = [
    { label: 'Сегодня', getDate: () => startOfDay(new Date()) },
    { label: 'Вчера', getDate: () => addDays(startOfDay(new Date()), -1) },
    { label: 'Неделя назад', getDate: () => addDays(startOfDay(new Date()), -7) },
  ];

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-3)' }}>
      <div className="jx-stack jx-stack--row" style={{ gap: 'var(--jx-space-2)' }}>
        {presets.map((preset) => {
          const presetDate = preset.getDate();
          const isActive = presetDate.getTime() === selected.getTime();
          return (
            <JxButton
              key={preset.label}
              variant={isActive ? 'primary' : 'secondary'}
              size="sm"
              onClick={() => handleChange(presetDate)}
            >
              {preset.label}
            </JxButton>
          );
        })}
      </div>
      <JxCalendar value={selected} onValueChange={handleChange} />
    </div>
  );
}

